-- Capture existing operators once; future web admins receive no host entitlement.
CREATE TABLE identity_host_operators(user_id text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,state text NOT NULL CHECK(state IN ('enabled','revoked')),origin text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE sessions ADD COLUMN reauth_until timestamptz;
ALTER TABLE drive_sessions ADD COLUMN reauth_until timestamptz;
CREATE TABLE identity_policy_keys(id integer PRIMARY KEY CHECK(id=1),cursor_key text NOT NULL CHECK(cursor_key ~ '^[0-9a-f]{64}$'));
CREATE TABLE identity_mutations(actor_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,key_hash text NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,status integer NOT NULL,etag text NOT NULL DEFAULT '',expires_at timestamptz NOT NULL,PRIMARY KEY(actor_id,key_hash));
CREATE INDEX identity_mutations_expiry ON identity_mutations(expires_at);
CREATE TABLE identity_admin_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid,action text NOT NULL,target_id text,outcome text NOT NULL CHECK(outcome IN ('success','denied')),request_id text NOT NULL,details jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(details)='object' AND details-'reasonCode'-'changedFields'='{}'::jsonb),occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX identity_admin_events_time ON identity_admin_events(occurred_at,id);
